CREATE TABLE IF NOT EXISTS "Users" ("UserId" TEXT NOT NULL PRIMARY KEY, "PassCode1" TEXT NOT NULL, "PassCode2" TEXT NOT NULL, "IsFirstLogin" INTEGER NOT NULL,  UNIQUE ("UserId") );

CREATE TABLE IF NOT EXISTS "Devices" ("DeviceId" text NOT NULL PRIMARY KEY, "UserId" text NOT NULL REFERENCES "Users"("UserId"), "DeviceName" text NOT NULL, "Make" text NOT NULL, "Model" text NOT NULL, "NumberOfFlows" bigint NOT NULL, "RepeatFlowSequence" boolean NOT NULL, "FlowSequenceEnd" bigint NOT NULL, "Mode" integer NOT NULL, "OperatingMax" bigint NOT NULL, "OperatingMin" bigint NOT NULL, "Latitude" bigint NOT NULL, "Longitude" bigint NOT NULL, "Altitude" bigint NOT NULL, "GenModel" integer NOT NULL, "UnitOfMeasurement" text NOT NULL, "Scale" bigint NOT NULL, UNIQUE ("DeviceId"));

CREATE TABLE IF NOT EXISTS "SensingFlows" ("FlowId" TEXT NOT NULL PRIMARY KEY, "DeviceId" TEXT NOT NULL REFERENCES "Devices"("DeviceId") ON DELETE CASCADE, "FlowType" INTEGER NOT NULL, "Scale" BIGINT NOT NULL, "Duration" BIGINT NOT NULL, "UnixEpochStart" BIGINT NOT NULL, "UnixEpochEnd" BIGINT NOT NULL, "Minimum" BIGINT NOT NULL, "Maximum" BIGINT NOT NULL, "UnitOfMeasurement" VARCHAR(16) NOT NULL, "DatasetFilename" TEXT NOT NULL DEFAULT '' );

CREATE TABLE IF NOT EXISTS "ActuationRules" ("RuleId" text NOT NULL PRIMARY KEY, "DeviceId" text NOT NULL REFERENCES "Devices"("DeviceId") ON DELETE CASCADE, "ConditionType" integer NOT NULL,        "ValueThreshold" bigint NOT NULL, "Scale" bigint NOT NULL, "TargetType" integer NOT NULL, "TargetDeviceName" text NOT NULL, "TargetActionValue" bigint NOT NULL, "IsChained" boolean NOT NULL,         "RuleIdIfConditionFalse" text NOT NULL DEFAULT '', "RuleIdIfConditionTrue" text NOT NULL DEFAULT '');
